    response = ""
    t = 0
    idx = 0

    # Parse t (number of test cases)
    items = input_str.strip().split()
    idx = 0
    t = int(items[idx]); idx += 1

    for _ in range(t):
        n = int(items[idx]); m = int(items[idx+1]); idx += 2

        cells = []
        for i in range(n):
            row = []
            for j in range(m):
                row.append(int(items[idx])); idx += 1
            cells.append(row)

        # Calculate anti-diagonal grouping
        # Group cells by (r+c) where r and c are 0-indexed
        xor_sums = {}
        for i in range(n):
            for j in range(m):
                val = cells[i][j]
                diag = i + j
                if diag not in xor_sums:
                    xor_sums[diag] = 0
                xor_sums[diag] ^= val

        # The winner is determined by XOR of all xor_sum values
        overall_xor = 0
        for v in xor_sums.values():
            overall_xor ^= v

        if overall_xor != 0:
            response += "Ashish\n"
        else:
            response += "Jeel\n"

    return response.rstrip('\n')

