    offers = []
    lines = input_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])
    offers = []
    for i in range(1, m + 1):
        if i < len(lines):
            l, r = map(int, lines[i].split())
            offers.append((l, r))

    result = []

    for x in range(1, n + 1):
        occupied = [False] * (n + 2)
        count = 0
        for l, r in offers:
            length = r - l + 1
            if length >= x:
                # Check if fully unoccupied
                fully_free = True
                for day in range(l, r + 1):
                    if occupied[day]:
                        fully_free = False
                        break
                if fully_free:
                    for day in range(l, r + 1):
                        occupied[day] = True
                    count += length
        result.append(count)

    return '\n'.join(map(str, result))

