import sys
from functools import lru_cache as memoize

def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n, k = int(first_line[0]), int(first_line[1])
    piles = list(map(int, lines[1].split())) if len(lines) > 1 else []

    @memoize
    def grundy(m):
        if m == 0:
            return 0
        reachable = {grundy(m - 1)}
        if m % 2 == 0:
            x = m // 2
            gx = grundy(x)
            if k % 2 == 1:
                reachable.add(gx)
            else:
                reachable.add(0)

        mex = 0
        while mex in reachable:
            mex += 1
        return mex

    xor_sum = 0
    for pile in piles:
        xor_sum ^= grundy(pile)

    return "Kevin" if xor_sum != 0 else "Nicky"

