import collections

def solution(s):
    lines = s.strip().split('\n')

    if not lines or not lines[0].strip():
        return "0\n\n"

    first_line = lines[0].split()
    n, k = int(first_line[0]), int(first_line[1])

    if n == 1:
        return "0\n\n"

    # Build adjacency list with edge indices
    adj = collections.defaultdict(list)
    lines_per_edge = min(len(lines) - 1, n - 1)

    for i in range(lines_per_edge):
        line = lines[i + 1].strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            edge_id = i + 2
            adj[u].append((v, edge_id))
            adj[v].append((u, edge_id))

    # For k=1, we select just one vertex - no edges connect different states
    if k == 1:
        return "0\n\n"

    # Try each vertex as a potential root for our k-vertex subgraph
    for root in range(1, n + 1):
        # Use BFS to collect exactly k vertices starting from root
        visited = {root}
        queue = collections.deque([root])
        current_count = 1

        while queue and current_count < k:
            u = queue.popleft()
            for v, _ in adj[u]:
                if v not in visited:
                    visited.add(v)
                    current_count += 1
                    queue.append(v)
                    if current_count == k:
                        break

        if current_count == k:
            # Found a subtree of size k, now count cut edges
            cut_edges = []
            for u in visited:
                for v, edge_id in adj[u]:
                    if v not in visited:
                        if edge_id not in cut_edges:
                            cut_edges.append(edge_id)

            cut_edges.sort()
            if cut_edges:
                return str(len(cut_edges)) + "\n" + " ".join(map(str, cut_edges))

    return "0\n\n"

