def solution(s):
    """
    Solves the Catniverse planet visiting problem.

    Counts the number of ways to visit exactly k planets starting from any planet,
    where each move from planet x can go to any unvisited planet y in [1, x+m].
    """
    from functools import lru_cache

    try:
        parts = s.strip().split()
        n, k, m = int(parts[0]), int(parts[1]), int(parts[2])
    except (ValueError, IndexError):
        return "0"

    MOD = 10**9 + 7

    # Edge case: visiting only 1 planet means just choosing the starting point
    if k == 1:
        return str(n % MOD)

    # Cannot visit more planets than exist
    if k > n or k <= 0 or n <= 0:
        return "0"

    @lru_cache(maxsize=None)
    def count_ways(current_pos, visited_set):
        """
        Count ways to complete the path from current position.
        """
        visited_count = len(visited_set)
        if visited_count == k:
            return 1

        total = 0
        # Try all valid next positions: [1, current_pos + m]
        for next_pos in range(1, current_pos + m + 1):
            if next_pos <= n and next_pos not in visited_set:
                total = (total + count_ways(next_pos, visited_set | {next_pos})) % MOD
        return total

    total_ways = 0
    for start in range(1, n + 1):
        total_ways = (total_ways + count_ways(start, frozenset([start]))) % MOD

    return str(total_ways)


