    vertex_ices = []
    for i in range(n):
        parts = list(map(int, lines[1 + i].split()))
        si = parts[0]
        ices = parts[1:] if si > 0 else []
        vertex_ices.append(ices)

    # Find max color needed = max ice creams at any vertex (clique size)
    max_color = 1
    for ices in vertex_ices:
        if len(ices) > max_color:
            max_color = len(ices)

    # Build conflict graph
    ice_adj = [[] for _ in range(m + 1)]
    for ices in vertex_ices:
        for i in range(len(ices)):
            for j in range(i + 1, len(ices)):
                u, v = ices[i], ices[j]
                if v not in ice_adj[u]:
                    ice_adj[u].append(v)
                if u not in ice_adj[v]:
                    ice_adj[v].append(u)

    # Greedy coloring: process ice creams by vertex order
    colors = [0] * (m + 1)
    for ice in range(1, m + 1):
        if colors[ice] != 0:
            continue
        used = set()
        for nb in ice_adj[ice]:
            if colors[nb] != 0:
                used.add(colors[nb])
        for c in range(1, max_color + 1):
            if c not in used:
                colors[ice] = c
                break

    # Build output
