    var_occurrences = set()
    var_to_clauses = [[] for _ in range(m + 1)]
    clause_literals = [list(set(abs(l) for l in cl)) for cl in clauses]

    for clause_idx, cl_abs in enumerate(clause_literals):
        for lit in cl_abs:
            var_to_clauses[lit].append(clause_idx)

    # Build adjacency list for the dependency graph
    adj = [[] for _ in range(m + 1)]
    for var in range(1, m + 1):
        for clause_idx in var_to_clauses[var]:
            for other_lit in clause_literals[clause_idx]:
                if other_lit != var:
                    adj[var].append(other_lit)

    visited_count = [0] * (m + 1)
    ans = 0

    for var in range(1, m + 1):
        if len(var_occurrences) == 0:
