def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        parts = list(map(int, lines[i + 1].split()))
        a, b, w = parts
        adj[a].append((b, w))

    q = int(lines[m + 2])
    queries = []
    for i in range(q):
        parts = list(map(int, lines[m + 3 + i].split()))
        v, s, t = parts
        queries.append((v, s, t))

    # Tarjan's algorithm for SCC
    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)
    scc_id = [-1] * (n + 1)
    scc_count = 0
    on_stack = [False] * (n + 1)
    stack = []
    timer = 0

    def dfs(u):
        nonlocal timer, scc_count
        disc[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack[u] = True

        for v, w in adj[u]:
            if disc[v] == -1:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            scc_count += 1
            while True:
                node = stack.pop()
                on_stack[node] = False
                scc_id[node] = scc_count
                if node == u:
                    break

    for i in range(1, n + 1):
        if disc[i] == -1:
            dfs(i)

    # Group edges by SCC
    scc_edges = [[] for _ in range(scc_count + 1)]
    scc_nodes = [[] for _ in range(scc_count + 1)]

    for u in range(1, n + 1):
        scc = scc_id[u]
        scc_nodes[scc].append(u)
        for v, w in adj[u]:
            if scc_id[v] == scc:
                scc_edges[scc].append(w)

    # Compute gcd for each SCC
    scc_gcd = [0] * (scc_count + 1)
    for sc in range(1, scc_count + 1):
        if not scc_edges[sc]:
            continue
        # Find gcd of all cycle lengths in this SCC
        # Use DFS to get spanning tree, then compute fundamental cycles
        nonlocal scc_count
        visited = set()
        dfs_tree = {}
        tree_order = []

        # Build DFS tree
        stack_nodes = list(scc_nodes[sc])
        while stack_nodes:
            u = stack_nodes.pop()
            if u in visited:
                continue
            visited.add(u)
            tree_order.append(u)
            for v, w in adj[u]:
                if scc_id[v] == sc and v not in visited:
                    tree_order.append(v)
                    dfs_tree[u] = v

        # For each SCC, compute minimum cycle
        g = 0
        for w in scc_edges[sc]:
            if w > g:
                g = w
            else:
                g = math.gcd(g, w)

        scc_gcd[sc] = g

    # Answer queries
    results = []
    for v, s, t in queries:
        if s == 0:
            results.append("YES")
        else:
            sc = scc_id[v]
            if sc == -1 or scc_gcd[sc] == 0:
                results.append("NO")
            else:
                g_cycle = scc_gcd[sc]
                gcd_val = math.gcd(g_cycle, t)
                if gcd_val > 0 and s % gcd_val == 0:
                    results.append("YES")
                else:
                    results.append("NO")

    return '\n'.join(results)

