def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    # Read roads
    roads = []
    for i in range(1, m + 1):
        u, v, x = map(int, lines[i].split())
        roads.append((u, v, x))

    # Read trains
    trains = []
    for i in range(1, m + k + 1):
        s, y = map(int, lines[i].split())
        trains.append((s, y))

    # Build road graph
    road_adj = [[] for _ in range(n + 1)]
    for u, v, x in roads:
        road_adj[u].append((v, x))
        road_adj[v].append((u, x))

    # Build full graph (roads + trains)
    full_adj = [list(road_adj[i]) for i in range(n + 1)]
    for s, y in trains:
        full_adj[1].append((s, y))
        full_adj[s].append((1, y))

    # Dijkstra function
    def dijkstra(adj, start):
        dist = [float('inf')] * (n + 1)
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))
        return dist

    full_dist = dijkstra(full_adj, 1)
    road_dist = dijkstra(road_adj, 1)

    # Group trains by destination city
    trains_by_city = {}
    for s, y in trains:
        if s not in trains_by_city:
            trains_by_city[s] = []
        trains_by_city[s].append(y)

    # Count closable trains
    closable_count = 0
    for city, costs in trains_by_city.items():
        # Count occurrences of each cost
        cost_counts = {}
        for y in costs:
            if y not in cost_counts:
                cost_counts[y] = 0
            cost_counts[y] += 1

        for y, count in cost_counts.items():
            if y > full_dist[city]:
                # Train cost is greater than shortest distance - always closable
                closable_count += count
            elif y == full_dist[city]:
                if road_dist[city] <= y:
                    # Road provides path with cost <= y - all trains closer at this cost are redundant
                    closable_count += count
                else:
                    # Only train-based path scores the optimal distance, need to keep 1
                    closable_count += count - 1

    return str(closable_count)

