def solution(s):
    N, x, M, y = map(int, s.split())
    d = abs(x - y)
    intersections = 0

    for r1 in range(1, N + 1):
        for r2 in range(1, M + 1):
            # Circles with radii r1 and r2, distance d apart
            # Intersect when |r1 - r2| ≤ d ≤ r1 + r2
            if abs(r1 - r2) <= d <= r1 + r2:
                intersections += 1

    # Total regions = 1 + N + M + intersections
    return 1 + N + M + intersections
